package com.medibook.service;
import com.medibook.dto.AuthDtos.Login;import com.medibook.entity.*;import com.medibook.repository.*;import com.medibook.security.JwtService;import org.junit.jupiter.api.Test;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.web.server.ResponseStatusException;import java.util.Optional;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class AuthServiceTest {
 @Test void invalidCredentialsUseGenericUnauthorizedResponse(){UserRepository users=mock(UserRepository.class);when(users.findByEmail("unknown@example.com")).thenReturn(Optional.empty());AuthService auth=new AuthService(users,mock(PatientProfileRepository.class),mock(PasswordEncoder.class),mock(JwtService.class));ResponseStatusException error=assertThrows(ResponseStatusException.class,()->auth.login(new Login("unknown@example.com","wrong")));assertEquals(401,error.getStatusCode().value());assertEquals("Invalid email or password",error.getReason());}
 @Test void inactiveAccountCannotLogin(){UserRepository users=mock(UserRepository.class);AppUser user=mock(AppUser.class);when(user.isActive()).thenReturn(false);when(users.findByEmail("person@example.com")).thenReturn(Optional.of(user));AuthService auth=new AuthService(users,mock(PatientProfileRepository.class),mock(PasswordEncoder.class),mock(JwtService.class));assertThrows(ResponseStatusException.class,()->auth.login(new Login("person@example.com","whatever")));}
 @Test void selfRegistrationCannotCreatePrivilegedDoctor(){UserRepository users=mock(UserRepository.class);when(users.findByEmail("doctor@example.com")).thenReturn(Optional.empty());AuthService auth=new AuthService(users,mock(PatientProfileRepository.class),mock(PasswordEncoder.class),mock(JwtService.class));var request=new com.medibook.dto.AuthDtos.Register("Doctor","doctor@example.com","StrongPassword123","DOCTOR");ResponseStatusException error=assertThrows(ResponseStatusException.class,()->auth.register(request));assertEquals(400,error.getStatusCode().value());verify(users,never()).save(any());}
}
